def rand_elem(seq, n=None):
    """returns a random element from seq n times. If n is None, it continues indefinitly"""
    return map(random.choice, repeat(seq, n) if n is not None else repeat(seq))

def print_full_name(*args, **kwargs):
    '''Decorator, print the full name of the decorated function.

    May be invoked as a simple, argument-less decorator (i.e. ``@print_doc1``)
    or with named arguments ``color``, ``bold``, or ``prefix``
    (eg. ``@print_doc1(color=utils.red, bold=True, prefix=' ')``).
    '''
    color = kwargs.get('color', default_color)
    bold = kwargs.get('bold', False)
    prefix = kwargs.get('prefix', '')
    tail = kwargs.get('tail', '')

    def real_decorator(func):
        '''real decorator function'''
        @wraps(func)
        def wrapper(*args, **kwargs):
            '''the wrapper function'''
            first_line = ''
            try:
                first_line = func.__module__ + '.' + func.__qualname__
            except AttributeError as exc:
                first_line = func.__name__
            print(color(prefix + first_line + tail, bold))
            return func(*args, **kwargs)
        return wrapper

    invoked = bool(not args or kwargs)
    if not invoked:
        # invoke decorator function which returns the wrapper function
        return real_decorator(func=args[0])

    return real_decorator

def convert_unicode_2_utf8(input):
    '''Return a copy of `input` with every str component encoded from unicode to
    utf-8.
    '''
    if isinstance(input, dict):
        try:
            # python-2.6
            return dict((convert_unicode_2_utf8(key), convert_unicode_2_utf8(value))
                        for key, value
                        in input.iteritems())
        except AttributeError:
            # since python-2.7 cf. http://stackoverflow.com/a/1747827
            # [the ugly eval('...') is required for a valid syntax on
            # python-2.6, cf. http://stackoverflow.com/a/25049535]
            return eval('''{convert_unicode_2_utf8(key): convert_unicode_2_utf8(value)
                           for key, value
                           in input.items()}''')
    elif isinstance(input, list):
        return [convert_unicode_2_utf8(element) for element in input]
    # elif order relevant: python2 vs. python3
    # cf. http://stackoverflow.com/a/19877309
    elif isinstance(input, str):
        return input
    else:
        try:
            if eval('''isinstance(input, unicode)'''):
                return input.encode('utf-8')
        except NameError:
            # unicode does not exist in python-3.x
            pass
        return input

def write_json(data, filename, gzip_mode=False):
    '''Write the python data structure as a json-Object to filename.'''

    open_file = open
    if gzip_mode:
        open_file = gzip.open

    try:
        with open_file(filename, 'wt') as fh:
            json.dump(obj=data, fp=fh, sort_keys=True)
    except AttributeError:
        # Python-2.6
        fh = open_file(filename, 'wt')
        json.dump(obj=data, fp=fh, sort_keys=True)
        fh.close()

def text_with_newlines(text, line_length=78, newline='\n'):
    '''Return text with a `newline` inserted after each `line_length` char.

    Return `text` unchanged if line_length == 0.
    '''
    if line_length > 0:
        if len(text) <= line_length:
            return text
        else:
            return newline.join([text[idx:idx+line_length]
                                 for idx
                                 in range(0, len(text), line_length)])
    else:
        return text

def lazy_val(func, with_del_hook=False):
    '''A memoize decorator for class properties.

    Return a cached property that is calculated by function `func` on first
    access.
    '''

    def hook_for(that):
        try:
            orig_del = that.__del__
        except AttributeError:
            orig_del = None

        def del_hook(*args, **kwargs):
            del that._cache[id(that)]
            del that._del_hook_cache[id(that)]
            if orig_del is not None:
                orig_del(that, *args, **kwargs)

        try:
            if orig_del is not None:
                that.__del__ = del_hook
        except AttributeError:
            # that.__del__ is a class property and cannot be changed by instance
            orig_del = None
        return del_hook

    def add_to_del_hook_cache(that):
        if with_del_hook:
            try:
                that._del_hook_cache[id(that)] = hook_for(that)
            except AttributeError:
                # when that._del_hook_cache not exists, it means it is not a
                # class property.  Then, we don't need a del_hook().
                pass

    @functools.wraps(func)
    def get(self):
        try:
            return self._cache[id(self)][func]
        except AttributeError:
            self._cache = {id(self): {}, }
            add_to_del_hook_cache(self)
        except KeyError:
            try:
                self._cache[id(self)]
            except KeyError:
                self._cache[id(self)] = {}
                add_to_del_hook_cache(self)
        val = self._cache[id(self)][func] = func(self)
        return val

    return property(get)

def _readlines(fname, fpointer1=open, fpointer2=open):  # pragma: no cover
    """Read all lines from file."""
    # fpointer1, fpointer2 arguments to ease testing
    try:
        with fpointer1(fname, "r") as fobj:
            return fobj.readlines()
    except UnicodeDecodeError:  # pragma: no cover
        with fpointer2(fname, "r", encoding="utf-8") as fobj:
            return fobj.readlines()

def match(Class, path, pattern, flags=re.I, sortkey=None, ext=None):
        """for a given path and regexp pattern, return the files that match"""
        return sorted(
            [
                Class(fn=fn)
                for fn in rglob(path, f"*{ext or ''}")
                if re.search(pattern, os.path.basename(fn), flags=flags) is not None
                and os.path.basename(fn)[0] != '~'  # omit temp files
            ],
            key=sortkey,
        )

def make_basename(self, fn=None, ext=None):
        """make a filesystem-compliant basename for this file"""
        fb, oldext = os.path.splitext(os.path.basename(fn or self.fn))
        ext = ext or oldext.lower()
        fb = String(fb).hyphenify(ascii=True)
        return ''.join([fb, ext])

def delete(self):
        """delete the file from the filesystem."""
        if self.isfile:
            os.remove(self.fn)
        elif self.isdir:
            shutil.rmtree(self.fn)

def readable_size(C, bytes, suffix='B', decimals=1, sep='\u00a0'):
        """given a number of bytes, return the file size in readable units"""
        if bytes is None:
            return
        size = float(bytes)
        for unit in C.SIZE_UNITS:
            if abs(size) < 1024 or unit == C.SIZE_UNITS[-1]:
                return "{size:.{decimals}f}{sep}{unit}{suffix}".format(
                    size=size,
                    unit=unit,
                    suffix=suffix,
                    sep=sep,
                    decimals=C.SIZE_UNITS.index(unit) > 0 and decimals or 0,  # B with no decimal
                )
            size /= 1024

def run(self):
        """Executed on startup of application"""
        for wsock in self.wsocks:
            wsock.run()
        for api in self.apis:
            api.run()

def shutdown(self):
        """Executed on shutdown of application"""
        for wsock in self.wsocks:
            wsock.shutdown()
        for api in self.apis:
            api.shutdown()

def request(self, url, method, data=None, headers=None):
        """Makes a HTTP call, formats response and does error handling.
        """
        http_headers = merge_dict(self.default_headers, headers or {})
        request_data = merge_dict({'api_key': self.apikey}, data or {})

        logger.info('HTTP %s REQUEST TO %s' % (method, url))

        start = datetime.datetime.now()

        try:
            response = requests.request(method=method, url=url, data=json.dumps(request_data),
                                        headers=http_headers)
        except exceptions.BadRequestError as e:
            return json.loads({'errors': e.content})

        duration = datetime.datetime.now() - start

        logger.info('RESPONSE %s DURATION %s.%s' % (response.encoding, duration.seconds,
                                                    duration.microseconds))

        return json.loads(response.content) if response.content else {}

def get(self, action, params=None, headers=None):
        """Makes a GET request
        """
        return self.request(make_url(self.endpoint, action), method='GET', data=params,
                            headers=headers)

def post(self, action, data=None, headers=None):
        """Makes a GET request
        """
        return self.request(make_url(self.endpoint, action), method='POST', data=data,
                            headers=headers)

def delete(self, action, headers=None):
        """Makes a GET request
        """
        return self.request(make_url(self.endpoint, action), method='DELETE',
                            headers=headers)

def rglob(dirname, pattern, dirs=False, sort=True):
    """recursive glob, gets all files that match the pattern within the directory tree"""
    fns = []
    path = str(dirname)
    if os.path.isdir(path):
        fns = glob(os.path.join(escape(path), pattern))
        dns = [fn for fn 
                in [os.path.join(path, fn)
                    for fn in os.listdir(path)] 
                if os.path.isdir(fn)]
        if dirs==True:
            fns += dns
        for d in dns:
            fns += rglob(d, pattern)
        if sort==True:
            fns.sort()
    else:
        log.warn("not a directory: %r" % path)
    return fns

def wait_all(futures, timeout=None):
    '''Wait for the completion of all futures in a list

    :param list future: a list of :class:`Future`\s
    :param timeout:
        The maximum time to wait. With ``None``, can block indefinitely.
    :type timeout: float or None

    :raises WaitTimeout: if a timeout is provided and hit
    '''
    if timeout is not None:
        deadline = time.time() + timeout
        for fut in futures:
            fut.wait(deadline - time.time())
    else:
        for fut in futures:
            fut.wait()

def value(self):
        '''The final value, if it has arrived

        :raises: AttributeError, if not yet complete
        :raises: an exception if the Future was :meth:`abort`\ed
        '''
        if not self._done.is_set():
            raise AttributeError("value")
        if self._failure:
            raise self._failure[0], self._failure[1], self._failure[2]
        return self._value

def on_finish(self, func):
        '''Assign a callback function to be run when successfully complete

        :param function func:
            A callback to run when complete. It will be given one argument (the
            value that has arrived), and it's return value is ignored.
        '''
        if self._done.is_set():
            if self._failure is None:
                backend.schedule(func, args=(self._value,))
        else:
            self._cbacks.append(func)

def on_abort(self, func):
        '''Assign a callback function to be run when :meth:`abort`\ed

        :param function func:
            A callback to run when aborted. It will be given three arguments:

                - ``klass``: the exception class
                - ``exc``: the exception instance
                - ``tb``: the traceback object associated with the exception
        '''
        if self._done.is_set():
            if self._failure is not None:
                backend.schedule(func, args=self._failure)
        else:
            self._errbacks.append(func)

def partial_results(self):
        '''The results that the RPC has received *so far*

        This may also be the complete results if :attr:`complete` is ``True``.
        '''
        results = []
        for r in self._results:
            if isinstance(r, Exception):
                results.append(type(r)(*deepcopy(r.args)))
            elif hasattr(r, "__iter__") and not hasattr(r, "__len__"):
                # pass generators straight through
                results.append(r)
            else:
                results.append(deepcopy(r))
        return results

def os_path_transform(self, s, sep=os.path.sep):
        """ transforms any os path into unix style """
        if sep == '/':
            return s
        else:
            return s.replace(sep, '/')

def transform(self, tr_list, files):
        """
        replaces $tokens$ with values
        will be replaced with config rendering
        """
        singular = False
        if not isinstance(files, list) and not isinstance(files, tuple):
            singular = True
            files = [files]

        for _find, _replace in tr_list:
            files = [opt.replace(_find, _replace) for opt in files]

        if singular:
            return files[0]
        else:
            return files

def resolve_dst(self, dst_dir, src):
        """
        finds the destination based on source
        if source is an absolute path, and there's no pattern, it copies the file to base dst_dir
        """
        if os.path.isabs(src):
            return os.path.join(dst_dir, os.path.basename(src))
        return os.path.join(dst_dir, src)

def assign(self, attrs):
        """Merge new attributes
        """
        for k, v in attrs.items():
            setattr(self, k, v)

def normalize_rust_function(self, function, line):
        """Normalizes a single rust frame with a function"""
        # Drop the prefix and return type if there is any
        function = drop_prefix_and_return_type(function)

        # Collapse types
        function = collapse(
            function,
            open_string='<',
            close_string='>',
            replacement='<T>',
            exceptions=(' as ',)
        )

        # Collapse arguments
        if self.collapse_arguments:
            function = collapse(
                function,
                open_string='(',
                close_string=')',
                replacement=''
            )

        if self.signatures_with_line_numbers_re.match(function):
            function = '{}:{}'.format(function, line)

        # Remove spaces before all stars, ampersands, and commas
        function = self.fixup_space.sub('', function)

        # Ensure a space after commas
        function = self.fixup_comma.sub(', ', function)

        # Remove rust-generated uniqueness hashes
        function = self.fixup_hash.sub('', function)

        return function

def normalize_cpp_function(self, function, line):
        """Normalizes a single cpp frame with a function"""
        # Drop member function cv/ref qualifiers like const, const&, &, and &&
        for ref in ('const', 'const&', '&&', '&'):
            if function.endswith(ref):
                function = function[:-len(ref)].strip()

        # Drop the prefix and return type if there is any if it's not operator
        # overloading--operator overloading syntax doesn't have the things
        # we're dropping here and can look curious, so don't try
        if '::operator' not in function:
            function = drop_prefix_and_return_type(function)

        # Collapse types
        function = collapse(
            function,
            open_string='<',
            close_string='>',
            replacement='<T>',
            exceptions=('name omitted', 'IPC::ParamTraits')
        )

        # Collapse arguments
        if self.collapse_arguments:
            function = collapse(
                function,
                open_string='(',
                close_string=')',
                replacement='',
                exceptions=('anonymous namespace', 'operator')
            )

        # Remove PGO cold block labels like "[clone .cold.222]". bug #1397926
        if 'clone .cold' in function:
            function = collapse(
                function,
                open_string='[',
                close_string=']',
                replacement=''
            )

        if self.signatures_with_line_numbers_re.match(function):
            function = '{}:{}'.format(function, line)

        # Remove spaces before all stars, ampersands, and commas
        function = self.fixup_space.sub('', function)

        # Ensure a space after commas
        function = self.fixup_comma.sub(', ', function)

        return function

def normalize_frame(
        self,
        module=None,
        function=None,
        file=None,
        line=None,
        module_offset=None,
        offset=None,
        normalized=None,
        **kwargs  # eat any extra kwargs passed in
    ):
        """Normalizes a single frame

        Returns a structured conglomeration of the input parameters to serve as
        a signature. The parameter names of this function reflect the exact
        names of the fields from the jsonMDSW frame output. This allows this
        function to be invoked by passing a frame as ``**a_frame``.

        Sometimes, a frame may already have a normalized version cached. If
        that exists, return it instead.

        """
        # If there's a cached normalized value, use that so we don't spend time
        # figuring it out again
        if normalized is not None:
            return normalized

        if function:
            # If there's a filename and it ends in .rs, then normalize using
            # Rust rules
            if file and (parse_source_file(file) or '').endswith('.rs'):
                return self.normalize_rust_function(
                    function=function,
                    line=line
                )

            # Otherwise normalize it with C/C++ rules
            return self.normalize_cpp_function(
                function=function,
                line=line
            )

        # If there's a file and line number, use that
        if file and line:
            filename = file.rstrip('/\\')
            if '\\' in filename:
                file = filename.rsplit('\\')[-1]
            else:
                file = filename.rsplit('/')[-1]
            return '{}#{}'.format(file, line)

        # If there's an offset and no module/module_offset, use that
        if not module and not module_offset and offset:
            return '@{}'.format(offset)

        # Return module/module_offset
        return '{}@{}'.format(module or '', module_offset)

def _do_generate(self, source_list, hang_type, crashed_thread, delimiter=' | '):
        """
        each element of signatureList names a frame in the crash stack; and is:
          - a prefix of a relevant frame: Append this element to the signature
          - a relevant frame: Append this element and stop looking
          - irrelevant: Append this element only after seeing a prefix frame
        The signature is a ' | ' separated string of frame names.
        """
        notes = []
        debug_notes = []

        # shorten source_list to the first signatureSentinel
        sentinel_locations = []
        for a_sentinel in self.signature_sentinels:
            if type(a_sentinel) == tuple:
                a_sentinel, condition_fn = a_sentinel
                if not condition_fn(source_list):
                    continue
            try:
                sentinel_locations.append(source_list.index(a_sentinel))
            except ValueError:
                pass
        if sentinel_locations:
            min_index = min(sentinel_locations)
            debug_notes.append(
                'sentinel; starting at "{}" index {}'.format(source_list[min_index], min_index)
            )
            source_list = source_list[min_index:]

        # Get all the relevant frame signatures. Note that these function signatures
        # have already been normalized at this point.
        new_signature_list = []
        for a_signature in source_list:
            # If the signature matches the irrelevant signatures regex, skip to the next frame.
            if self.irrelevant_signature_re.match(a_signature):
                debug_notes.append('irrelevant; ignoring: "{}"'.format(a_signature))
                continue

            # If the frame signature is a dll, remove the @xxxxx part.
            if '.dll' in a_signature.lower():
                a_signature = a_signature.split('@')[0]

                # If this trimmed DLL signature is the same as the previous frame's, skip it.
                if new_signature_list and a_signature == new_signature_list[-1]:
                    continue

            new_signature_list.append(a_signature)

            # If the signature does not match the prefix signatures regex, then it is the last
            # one we add to the list.
            if not self.prefix_signature_re.match(a_signature):
                debug_notes.append('not a prefix; stop: "{}"'.format(a_signature))
                break

            debug_notes.append('prefix; continue iterating: "{}"'.format(a_signature))

        # Add a special marker for hang crash reports.
        if hang_type:
            debug_notes.append(
                'hang_type {}: prepending {}'.format(hang_type, self.hang_prefixes[hang_type])
            )
            new_signature_list.insert(0, self.hang_prefixes[hang_type])

        signature = delimiter.join(new_signature_list)

        # Handle empty signatures to explain why we failed generating them.
        if signature == '' or signature is None:
            if crashed_thread is None:
                notes.append(
                    "CSignatureTool: No signature could be created because we do not know which "
                    "thread crashed"
                )
                signature = "EMPTY: no crashing thread identified"
            else:
                notes.append(
                    "CSignatureTool: No proper signature could be created because no good data "
                    "for the crashing thread ({}) was found".format(crashed_thread)
                )
                try:
                    signature = source_list[0]
                except IndexError:
                    signature = "EMPTY: no frame data available"

        return signature, notes, debug_notes

def _clean_tag(t):
    """Fix up some garbage errors."""
    # TODO: when score present, include info.
    t = _scored_patt.sub(string=t, repl='')
    if t == '_country_' or t.startswith('_country:'):
        t = 'nnp_country'
    elif t == 'vpb':
        t = 'vb'  # "carjack" is listed with vpb tag.
    elif t == 'nnd':
        t = 'nns'  # "abbes" is listed with nnd tag.
    elif t == 'nns_root:':
        t = 'nns'  # 'micros' is listed as nns_root.
    elif t == 'root:zygote':
        t = 'nn'  # 'root:zygote' for zygote. :-/
    elif t.startswith('root:'):
        t = 'uh'  # Don't know why, but these are all UH tokens.
    elif t in ('abbr_united_states_marine_corps', 'abbr_orange_juice'):
        t = "abbreviation"
    elif t == '+abbreviation':
        t = 'abbreviation'
    elif t.startswith('fw_misspelling:'):
        t = 'fw'
    return t

def local_settings(settings, prefix):
    """Localizes the settings for the dotted prefix.
    For example, if the prefix where 'xyz'::

        {'xyz.foo': 'bar', 'other': 'something'}

    Would become::

        {'foo': 'bar'}

    Note, that non-prefixed items are left out and the prefix is dropped.
    """
    prefix = "{}.".format(prefix)
    new_settings = {k[len(prefix):]: v for k, v in settings.items()
                    if k.startswith(prefix)}
    return new_settings

